def split_row(line: str):
    """Split a CSV row, allowing commas and doubled quotes in quoted fields."""
    fields = []
    field = []
    in_quotes = False
    index = 0

    while index < len(line):
        char = line[index]

        if in_quotes:
            if char == '"':
                # Two quotes in a quoted field represent one literal quote.
                if index + 1 < len(line) and line[index + 1] == '"':
                    field.append('"')
                    index += 2
                    continue
                in_quotes = False
            else:
                field.append(char)
        elif char == ',' :
            fields.append(''.join(field))
            field = []
        elif char == '"' and not field:
            in_quotes = True
        else:
            field.append(char)

        index += 1

    fields.append(''.join(field))
    return fields
